package org.bukkit.event.player; public class PlayerInteractEvent { public org.bukkit.inventory.ItemStack item; public org.bukkit.entity.Player player; public org.bukkit.block.Block block; public boolean cancelled; public org.bukkit.event.block.Action getAction(){return org.bukkit.event.block.Action.RIGHT_CLICK_BLOCK;} public org.bukkit.inventory.EquipmentSlot getHand(){return org.bukkit.inventory.EquipmentSlot.HAND;} public org.bukkit.block.Block getClickedBlock(){return block;} public org.bukkit.block.BlockFace getBlockFace(){return org.bukkit.block.BlockFace.UP;} public org.bukkit.inventory.ItemStack getItem(){return item;} public org.bukkit.entity.Player getPlayer(){return player;} public void setCancelled(boolean b){cancelled=b;} }
